let v = typeof msg.payload === "string" ? JSON.parse(msg.payload) : msg.payload;
if (v.status !== "success") return null;
let s = context.get("statistics") || {count:0};
for (let k of ["temperature","humidity","pressure"]) {
  if (!Number.isFinite(Number(v[k]))) return null;
}
s.count++;
for (let k of ["temperature","humidity","pressure"]) {
  let x=Number(v[k]);
  let a=s[k] || {minimum:x,maximum:x,sum:0};
  a.minimum=Math.min(a.minimum,x);a.maximum=Math.max(a.maximum,x);a.sum+=x;a.average=a.sum/s.count;s[k]=a;
}
context.set("statistics",s);msg.payload=s;return msg;
